package com.sunwayworld.framework.utils;

import com.sunwayworld.framework.exception.ReflectionException;
import com.sunwayworld.framework.exception.core.ApplicationRuntimeException;
import com.sunwayworld.owned.internal.context.OwnedApplicationContext;
import java.lang.annotation.Annotation;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import org.springframework.context.ApplicationContext;

public abstract class ReflectionUtils {
    public ReflectionUtils() { }
    public static final boolean isReadMethod(Method m){String n=m.getName();return (n.startsWith("CGLIB$get")||n.startsWith("get")||n.startsWith("CGLIB$is")||n.startsWith("is"))&&m.getParameterCount()==0;}
    public static final boolean isWriteMethod(Method m){String n=m.getName();return (n.startsWith("CGLIB$set")||n.startsWith("set"))&&m.getParameterCount()==1;}
    public static final Method findReadMethod(Class<?> type,String name){Method m=findMethod(type,"get"+name);return m!=null?m:findMethod(type,"is"+name);}
    public static final Method findWriteMethod(Class<?> type,String name){for(Method m:type.getMethods())if(m.getName().equalsIgnoreCase("set"+name)&&m.getParameterCount()==1)return m;return null;}
    public static final Method getUniqueMethodByName(Class<?> type,String name){List<MethodWrapper> list=getMethodWrapperListByName(type,name);if(list.isEmpty())return null;if(list.size()==1)return list.get(0).getMethod();throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.DUPLICATED_METHOD_NAME",type.toString(),name);}
    public static final List<MethodWrapper> getMethodWrapperListByName(Class<?> type,String name){return getMethodWrapperList(type).stream().filter(w->w.getMethod().getName().equalsIgnoreCase(name)).collect(Collectors.toList());}
    public static List<Method> getMethodList(Class<?> type,int... modifiers){return getMethodWrapperList(type).stream().filter(w->{for(int modifier:modifiers)if((w.getMethod().getModifiers()&modifier)==0)return false;return true;}).map(MethodWrapper::getMethod).collect(Collectors.toList());}
    public static List<MethodWrapper> getAnnotatedMethodList(Class<?> type,Class<? extends Annotation> annotation){return getMethodWrapperList(type).stream().filter(w->w.getAnnotationList().stream().anyMatch(a->a.annotationType().equals(annotation))).collect(Collectors.toList());}
    public static List<Class<?>> getAllInterfaces(Class<?> type){if(type==null||type==Object.class)return Collections.emptyList();List<Class<?>> out=new ArrayList<>();for(Class<?> c=type;c!=null;c=c.getSuperclass())for(Class<?> i:c.getInterfaces()){out.add(i);out.addAll(getAllInterfaces(i));}return out;}
    public static final Method findMethod(Class<?> type,String name){return findMethod(type,name,new Class<?>[0]);}
    public static final Method findMethod(Class<?> type,String name,Class<?>... params){for(MethodWrapper w:getMethodWrapperList(type)){Method m=w.getMethod();if(!m.getName().equalsIgnoreCase(name))continue;Type[] p=w.getParamTypes();if(params!=null&&params.length>0){if(p.length!=params.length)continue;boolean ok=true;for(int i=0;i<params.length;i++)if(!p[i].getTypeName().startsWith(params[i].getTypeName()))ok=false;if(!ok)continue;}else if(p.length!=0)continue;return m;}return null;}
    public static final Method findMethodWithReturnType(Class<?> type,String name,Type returnType){List<MethodWrapper> list=getMethodWrapperList(type).stream().filter(w->w.getMethod().getName().equalsIgnoreCase(name)&&Objects.equals(w.getReturnType(),returnType)).collect(Collectors.toList());if(list.isEmpty())return null;if(list.size()==1)return list.get(0).getMethod();throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.DUPLICATED_METHOD_NAME_WITH_RETURNTYPE",type.toString(),name,returnType.getTypeName());}
    public static final Object invokeMethod(Method m,Object target){return invokeMethod(m,target,new Object[0]);}
    public static final Object invokeMethod(Method m,Object target,Object... args){boolean old=m.isAccessible();try{if(!old)m.setAccessible(true);return m.invoke(target,args);}catch(IllegalAccessException|IllegalArgumentException|InvocationTargetException e){throw new ApplicationRuntimeException(e,e.getMessage());}finally{if(!old)m.setAccessible(false);}}
    public static final void invokeWriteMethod(Object target,String name,Object value){Method m=findWriteMethod(target.getClass(),name);if(m==null)throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.FIELD_NO_SETTER",target.getClass().getName(),name);invokeMethod(m,target,value);}
    public static final Object invokeReadMethod(Object target,String name){Method m=findReadMethod(target.getClass(),name);if(m!=null)return invokeMethod(m,target);throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.FIELD_NO_GETTER",target.getClass().getName(),name);}
    public static List<Field> getFiledList(Class<?> type,int... modifiers){return getFieldWrapperList(type).stream().filter(w->{for(int modifier:modifiers)if((w.getField().getModifiers()&modifier)==0)return false;return true;}).map(FieldWrapper::getField).collect(Collectors.toList());}
    public static Field findField(Class<?> type,String name){return getFieldWrapperList(type).stream().filter(w->w.getField().getName().equalsIgnoreCase(name)).map(FieldWrapper::getField).findAny().orElse(null);}
    public static final Field findFieldOfReadMethod(Method m){if(!isReadMethod(m))throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.METHOD_IS_NOT_GETTER",m.toString());Class<?> raw=ClassUtils.getRawType(m.getDeclaringClass());String n=m.getName();String field=n.startsWith("is")?n.substring(2):n.substring(3);Field f=findField(raw,field);if(f==null)throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.NO_FIELD_FOR_GETTER_METHOD",n);if(!f.getType().getTypeName().equals(m.getReturnType().getTypeName()))throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.FIELD_FOR_GETTER_METHOD_TYPE_UNMATCH",n);return f;}
    public static final Field findFieldOfWriteMethod(Method m){if(!isWriteMethod(m))throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.METHOD_IS_NOT_SETTER",m.toString());String field=StringUtils.uncapitalize(m.getName().substring(3));Field f=findField(m.getDeclaringClass(),field);if(f==null)throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.NO_FIELD_FOR_SETTER_METHOD",m.getName());if(!f.getType().getTypeName().equals(m.getReturnType().getTypeName()))throw new ApplicationRuntimeException("GIKAM.EXCEPTION.REFLECTION.FIELD_FOR_SETTER_METHOD_TYPE_UNMATCH",m.getName());return f;}
    public static final Object getFieldValue(Object target,String name){Field f=findField(target.getClass(),name);if(f==null)return null;try{accessible(f);return f.get(target);}catch(IllegalArgumentException|IllegalAccessException e){throw new ReflectionException(e);}}
    public static final void setFieldValue(Object target,String name,Object value){Field f=findField(target.getClass(),name);if(f==null)return;try{accessible(f);f.set(target,value);}catch(IllegalArgumentException|IllegalAccessException e){throw new ReflectionException(e);}}
    public static final void setStaticFieldValue(Class<?> type,String name,Object value){Field f=findField(type,name);if(f==null)return;try{accessible(f);f.set(null,value);}catch(IllegalArgumentException|IllegalAccessException|SecurityException e){throw new ReflectionException(e);}}
    public static final <T extends Annotation>T getAnnotation(Class<?> type,Class<T> annotation){for(Annotation a:getClassAnnotationList(type))if(a.annotationType().equals(annotation))return annotation.cast(a);return null;}
    public static final <T extends Annotation>T getAnnotation(Method method,Class<T> annotation){for(MethodWrapper w:getMethodWrapperList(method.getDeclaringClass()))if(w.getMethod().equals(method))for(Annotation a:w.getAnnotationList())if(a.annotationType().equals(annotation))return annotation.cast(a);return null;}
    public static final boolean isValidBeanProperty(Class<?> type,Field field){return !field.getName().equalsIgnoreCase("readonly")&&findReadMethod(type,field.getName())!=null&&findWriteMethod(type,field.getName())!=null;}
    public static List<ConcreteMethod> getConcreteMethodByAnnotation(Class<? extends Annotation> beanAnnotation,Class<? extends Annotation> methodAnnotation){List<ConcreteMethod> out=new ArrayList<>();ApplicationContext ctx=OwnedApplicationContext.getApplicationContext();if(ctx==null)return out;for(Object bean:ctx.getBeansWithAnnotation(beanAnnotation).values()){Class<?> raw=ClassUtils.getRawType(bean.getClass());for(MethodWrapper w:getAnnotatedMethodList(raw,methodAnnotation))out.add(new ConcreteMethod(raw,w.getMethod()));}return Collections.unmodifiableList(out);}
    public static final String getSimpleSignature(Class<?> type,Method method){StringBuilder b=new StringBuilder(type.getName()).append('.').append(method.getName()).append('(');Type[] p=method.getGenericParameterTypes();for(int i=0;i<p.length;i++){if(i>0)b.append(',');b.append(simpleName(p[i]));}return b.append(')').toString();}
    public static List<Annotation> getClassAnnotationList(Class<?> type){type=ClassUtils.getRawType(type);List<Annotation> out=new ArrayList<>();for(Class<?> c=type;c!=null;c=c.getSuperclass())addAnnotations(out,c.getDeclaredAnnotations());for(Class<?> c=type;c!=null;c=c.getSuperclass())for(Class<?> i:c.getInterfaces())addInterfaceAnnotations(out,i);return out;}
    public static List<FieldWrapper> getFieldWrapperList(Class<?> type){type=ClassUtils.getRawType(type);List<FieldWrapper> out=new ArrayList<>();for(Class<?> c=type;c!=null;c=c.getSuperclass())for(Field f:c.getDeclaredFields())if(out.stream().noneMatch(w->w.getField().getName().equals(f.getName())))out.add(new FieldWrapper(type,f,resolveType(f.getGenericType())));for(Field f:type.getFields())if(out.stream().noneMatch(w->w.getField().getName().equals(f.getName())))out.add(new FieldWrapper(type,f,resolveType(f.getGenericType())));return out;}
    public static List<MethodWrapper> getMethodWrapperList(Class<?> type){type=ClassUtils.getRawType(type);List<MethodWrapper> out=new ArrayList<>();collectMethods(type,type,out);out.sort(Comparator.comparing(w->w.getMethod().getName()));return out;}
    private static void collectMethods(Class<?> root,Class<?> type,List<MethodWrapper> out){if(type==null)return;for(Method m:type.getDeclaredMethods()){if(m.getName().startsWith("lambda$"))continue;Type[] raw=m.getGenericParameterTypes();Type[] params=new Type[raw.length];for(int i=0;i<raw.length;i++)params[i]=resolveType(raw[i]);MethodWrapper w=new MethodWrapper(root,m,params,resolveType(m.getGenericReturnType()),Arrays.asList(m.getDeclaredAnnotations()));MethodWrapper existing=out.stream().filter(x->x.equals(w)).findAny().orElse(null);if(existing==null)out.add(w);else for(Annotation a:w.getAnnotationList())existing.addAnnotation(a);}for(Class<?> i:type.getInterfaces())collectMethods(root,i,out);collectMethods(root,type.getSuperclass(),out);}
    private static void addAnnotations(List<Annotation> out,Annotation[] values){for(Annotation a:values)if(out.stream().noneMatch(x->x.annotationType().equals(a.annotationType())))out.add(a);}
    private static void addInterfaceAnnotations(List<Annotation> out,Class<?> i){addAnnotations(out,i.getDeclaredAnnotations());for(Class<?> p:i.getInterfaces())addInterfaceAnnotations(out,p);}
    private static void accessible(Field f){if(!f.isAccessible())f.setAccessible(true);}
    private static String simpleName(Type t){if(t instanceof Class<?>)return ((Class<?>)t).getSimpleName();String n=t.getTypeName();return n.replaceAll("([a-zA-Z]+\\.)+","");}
    private static Type resolveType(Type type){if(type instanceof ParameterizedType)return ((ParameterizedType)type).getRawType();if(type instanceof TypeVariable)return Object.class;if(type instanceof GenericArrayType)return Object[].class;return type;}

    public static class FieldWrapper { private final Class<?> declaringClass;private final Field field;private final Type type;public FieldWrapper(Class<?> c,Field f,Type t){declaringClass=c;field=f;type=t;}public Class<?> getDeclaringClass(){return declaringClass;}public Field getField(){return field;}public Type getType(){return type;}public String toString(){int m=field.getModifiers();return (m==0?"":Modifier.toString(m)+" ")+type.getTypeName()+" "+declaringClass.getTypeName()+"."+field.getName();}}
    public static class MethodWrapper { private final Class<?> declaringClass;private final Method method;private final Type returnType;private final Type[] paramTypes;private final List<Annotation> annotationList;public MethodWrapper(Class<?> c,Method m,Type[] p,Type r,List<Annotation> a){declaringClass=c;method=m;paramTypes=p;returnType=r;annotationList=new ArrayList<>(a);}public Class<?> getDeclaringClass(){return declaringClass;}public Method getMethod(){return method;}public Type getReturnType(){return returnType;}public Type[] getParamTypes(){return paramTypes;}public List<Annotation> getAnnotationList(){return annotationList;}public void addAnnotation(Annotation a){if(annotationList.stream().noneMatch(x->x.annotationType().equals(a.annotationType())))annotationList.add(a);}public boolean equals(Object o){if(o==null)return false;if(o==this)return true;if(!(o instanceof MethodWrapper))return false;MethodWrapper w=(MethodWrapper)o;if(!method.getName().equals(w.method.getName())||paramTypes.length!=w.paramTypes.length)return false;for(int i=0;i<paramTypes.length;i++)if(!Objects.equals(paramTypes[i].getTypeName(),w.paramTypes[i].getTypeName()))return false;return true;}public String toString(){return method.toGenericString();}}
    public static class ConcreteMethod { private final Class<?> declaringClass;private final Method method;public ConcreteMethod(Class<?> c,Method m){declaringClass=c;method=m;}public Class<?> getDeclaringClass(){return declaringClass;}public Method getMethod(){return method;}}
    static class InternalCache { static final Map<Class<?>,List<MethodWrapper>> CLASS_METHOD_CONTAINER=new ConcurrentHashMap<>();static final Map<String,Method> CLASS_PROPERTY_READ_METHOD_CONTAINER=new ConcurrentHashMap<>();static final Map<Class<?>,List<FieldWrapper>> CLASS_FIELD_CONTAINER=new ConcurrentHashMap<>();static final Map<Class<?>,List<Annotation>> CLASS_ANNOTATION_CONTAINER=new ConcurrentHashMap<>();static final Map<String,Annotation> METHOD_ANNOTATION_CONTAINER=new ConcurrentHashMap<>();private InternalCache(){} }
}
